insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q03', 'a1-m1-l4', 3, 'fill_blank', '«Я из Узбекистана» — «из» + joy nomi = … dan. «Я в Ташкенте» — «в» = … da (yashash joyi).', '{"sentence":"Я ___ Узбекистана.","options":["из","в","на","до"],"correctIndex":0}'::jsonb, 'Я ___ Узбекистана.', array['из', 'в', 'на', 'до'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q04', 'a1-m1-l4', 4, 'listening', '«Я живу в Ташкенте» — «Men Toshkentda yashayman». «живу» — yashayman.', '{"speakText":"Я живу в Ташкенте.","promptUz":"Esiting va to''g''ri tarjimani tanlang.","options":["Men Toshkentda yashayman","Men Toshkentdanman","Men Samarqandda yashayman","Toshkent juda katta"],"correctIndex":0}'::jsonb, 'Я живу в Ташкенте.', array['Men Toshkentda yashayman', 'Men Toshkentdanman', 'Men Samarqandda yashayman', 'Toshkent juda katta'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q05', 'a1-m1-l4', 5, 'word_selection', '«Откуда» — qayerdan. «Где» — qayerda. «Куда» — qayerga. «Когда» — qachon.', '{"promptUz":"Qayerdan?","options":["откуда","где","куда","когда"],"correctIndex":0}'::jsonb, 'Qayerdan?', array['откуда', 'где', 'куда', 'когда'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q06', 'a1-m1-l4', 6, 'sentence_building', '«Я живу в Москве» — «Men Moskvada yashayman». «в» + joy = … da.', '{"correct":["Я","живу","в","Москве","."],"distractors":["из","он","на"]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q07', 'a1-m1-l4', 7, 'true_false', '«Мы из России» — «Biz Rossiyadanmiz». «из» qo''shimchasi «dan» ma''nosini beradi.', '{"ruText":"Мы из России.","uzTranslation":"Biz Rossiyadanmiz.","isTrue":true}'::jsonb, 'Мы из России.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q08', 'a1-m1-l4', 8, 'multiple_choice', '«Где ты живёшь?» — «Qayerda yashaysan?» (joy so''raladi). «Откуда ты?» esa qayerdan ekanligingizni so''raydi.', '{"prompt":"«Где ты живёшь?» ning to''g''ri tarjimasini tanlang.","promptLang":"uz","options":["Qayerda yashaysan?","Qayerdansan?","Qachon yashaysan?","Kim yashaydi?"],"correctIndex":0}'::jsonb, '«Где ты живёшь?» ning to''g''ri tarjimasini tanlang.', array['Qayerda yashaysan?', 'Qayerdansan?', 'Qachon yashaysan?', 'Kim yashaydi?'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q09', 'a1-m1-l4', 9, 'word_matching', 'Manzil iboralari: «Откуда ты» — Qayerdansan, «живу» — yashayman, «город» — shahar.', '{"pairs":[{"ru":"Откуда ты?","uz":"Qayerdansan?"},{"ru":"Я из Узбекистана","uz":"Men O''zbekistondaman"},{"ru":"живу","uz":"yashayman"},{"ru":"город","uz":"shahar"}]}'::jsonb, '', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q10', 'a1-m1-l4', 10, 'translation', '«Я живу в Москве» — «Men Moskvada yashayman». «Москве» — «Москва» so''zining kelishik shakli.', '{"direction":"uz_to_ru","source":"Men Moskvada yashayman.","accepted":["я живу в москве","я живу в москве?"]}'::jsonb, 'Men Moskvada yashayman.', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q11', 'a1-m1-l4', 11, 'listening', '«Откуда ты?» — «Qayerdansan?». «Где ты живёшь?» esa «Qayerda yashaysan?» bo''lardi.', '{"speakText":"Откуда ты?","promptUz":"Esiting va to''g''ri savolni tanlang.","options":["Qayerdansan?","Qayerda yashaysan?","Qachon kelding?","Kim borsan?"],"correctIndex":0}'::jsonb, 'Откуда ты?', array['Qayerdansan?', 'Qayerda yashaysan?', 'Qachon kelding?', 'Kim borsan?'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l4-q12', 'a1-m1-l4', 12, 'multiple_choice', '«в» + joy (в Ташкенте) — «…da» (yashash, bo''lish joyi) ma''nosini bildiradi.', '{"prompt":"«Я живу в Ташкенте» gapidagi «в» nimani bildiradi?","promptLang":"uz","options":["Joyni (Toshkentda)","Vaqtni (soatda)","Sababni","Og''irlikni"],"correctIndex":0}'::jsonb, '«Я живу в Ташкенте» gapidagi «в» nimani bildiradi?', array['Joyni (Toshkentda)', 'Vaqtni (soatda)', 'Sababni', 'Og''irlikni'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q01', 'a1-m1-l5', 1, 'multiple_choice', 'Dialogda Dilshod O''zbekistondan, Mariya esa Rossiyadan ekanligi aytilgan.', '{"prompt":"Ushbu dialogda qaysi ikki mamlakat tilga olinadi?","promptLang":"uz","options":["O''zbekiston va Rossiya","Qozog''iston va Turkiya","Xitoy va Yaponiya","Hindiston va Pokiston"],"correctIndex":0}'::jsonb, 'Ushbu dialogda qaysi ikki mamlakat tilga olinadi?', array['O''zbekiston va Rossiya', 'Qozog''iston va Turkiya', 'Xitoy va Yaponiya', 'Hindiston va Pokiston'], '0'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
insert into public.lesson_exercises (id, lesson_id, order_index, exercise_type, explanation_uz, payload, question_text, options, correct_answer) values ('a1-m1-l5-q02', 'a1-m1-l5', 2, 'translation', '«Приятно познакомиться!» — tanishuv oxirida aytiladigan ibora.', '{"direction":"ru_to_uz","source":"Приятно познакомиться!","accepted":["tanishganimdan xursandman","tanishganimizdan xursandman","tanishganimiz yoqimli"]}'::jsonb, 'Приятно познакомиться!', null, 'null'::jsonb) on conflict (id) do update set lesson_id = excluded.lesson_id, order_index = excluded.order_index, exercise_type = excluded.exercise_type, explanation_uz = excluded.explanation_uz, payload = excluded.payload, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer;
